<template><main v-if="manufacturer" class="page"><section class="hero"><div class="wrap"><nav><NuxtLink to="/spec-library">Spec Library</NuxtLink> / <NuxtLink :to="`/spec-library/${slug}`">{{title}}</NuxtLink> / {{manufacturer}}</nav><div class="kicker">UMS MACHINERY SPECIFICATION LIBRARY</div><h1>{{manufacturer}} {{activeType||title}} Specifications</h1><p>{{manufacturerMachines.length}} historical machines · {{models.length}} model{{models.length===1?'':'s'}}</p></div></section><section class="wrap section"><div v-if="availableTypes.length>1" class="type-switch"><div class="label">MACHINE TYPES</div><NuxtLink v-for="type in availableTypes" :key="type" :to="{path:`/spec-library/${slug}/${manufacturerSlug}`,query:{type}}" :class="['type-link',{active:type===activeType}]">{{type}}</NuxtLink></div><div class="label">{{activeType?'MACHINE TYPE':'WEB_DESC TYPES REPRESENTED'}}</div><div class="types"><span v-if="activeType">{{activeType}}</span><span v-else v-for="type in availableTypes" :key="type">{{type}}</span></div><h2>{{manufacturer}} {{activeType?activeType:''}} Models</h2><input v-model="q" class="search" type="search" :placeholder="`Search ${manufacturer} model`"><div class="grid"><NuxtLink v-for="m in filtered" :key="m.slug" :to="modelLink(m.slug)" class="card"><strong>{{m.model}}</strong><span>{{m.count}} historical record{{m.count===1?'':'s'}} · {{yearLabel(m)}}</span></NuxtLink></div></section></main><main v-else class="missing"><h1>{{title}} manufacturer not found</h1><NuxtLink :to="`/spec-library/${slug}`">Browse {{title}}</NuxtLink></main></template>
<script setup>
import historicalMachines from '~/assets/data/historical-machines.json'
const props=defineProps({group:{type:String,required:true},title:{type:String,required:true},slug:{type:String,required:true}}),route=useRoute(),q=ref(''),manufacturerSlug=String(route.params.manufacturer||''),clean=s=>String(s||'').trim(),slugify=s=>clean(s).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),machineType=m=>clean(m.WebDesc||m.Web_Desc)
// Historical JSON presence is the library inclusion rule. Status fields are intentionally ignored.
const groupMachines=historicalMachines.filter(m=>clean(m.Groups)===props.group),manufacturer=[...new Set(groupMachines.map(m=>clean(m.Manufacturer)).filter(Boolean))].find(name=>slugify(name)===manufacturerSlug)||'';if(!manufacturer)setResponseStatus(404)
const allManufacturerMachines=manufacturer?groupMachines.filter(m=>clean(m.Manufacturer)===manufacturer):[],availableTypes=[...new Set(allManufacturerMachines.map(machineType).filter(Boolean))].sort((a,b)=>a.localeCompare(b)),requestedType=clean(route.query.type),activeType=availableTypes.includes(requestedType)?requestedType:'',manufacturerMachines=activeType?allManufacturerMachines.filter(m=>machineType(m)===activeType):allManufacturerMachines
const models=[...new Set(manufacturerMachines.map(m=>clean(m.Model)).filter(Boolean))].sort((a,b)=>a.localeCompare(b)).map(model=>{const rows=manufacturerMachines.filter(m=>clean(m.Model)===model),years=rows.map(m=>clean(m.Year)).filter(Boolean).sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));return{model,slug:slugify(model),count:rows.length,firstYear:years[0]||'',lastYear:years.at(-1)||''}}),filtered=computed(()=>{const x=q.value.trim().toLowerCase();return x?models.filter(m=>m.model.toLowerCase().includes(x)):models}),yearLabel=m=>!m.firstYear?'year varies/not recorded':m.firstYear===m.lastYear?m.firstYear:`${m.firstYear}–${m.lastYear}`,modelLink=model=>({path:`/spec-library/${props.slug}/${manufacturerSlug}/${model}`,query:activeType?{type:activeType}:{}})
useSeoMeta({title:()=>manufacturer?`${manufacturer} ${activeType||props.title} Specifications | UMS Spec Library`:`${props.title} Specifications | UMS`,description:()=>manufacturer?`Historical ${manufacturer} ${(activeType||props.title).toLowerCase()} specifications by model and year from UMS records.`:`Historical ${props.title.toLowerCase()} specifications.`});useHead(()=>({link:[{rel:'canonical',href:`https://www.usedmachinerysource.com/spec-library/${props.slug}/${manufacturerSlug}`}]}))
</script><style scoped>.page{color:#17273a;background:#fff;padding-bottom:60px}.wrap{max-width:1200px;margin:0 auto;padding:0 28px}.hero{background:linear-gradient(105deg,#071b33,#0d2c52);color:#fff;padding:48px 0;border-bottom:4px solid #f47b20}.hero nav,.hero a{color:#c8d9eb}.kicker,.label{font-size:.78rem;font-weight:900;letter-spacing:.12em;color:#f47b20;margin:18px 0 8px}.hero h1{font-size:clamp(2.2rem,4vw,3.3rem);margin:0 0 12px}.section{padding-top:44px}.type-switch{margin-bottom:24px}.type-link{display:inline-block;margin:0 8px 8px 0;padding:8px 11px;border:1px solid #d8e0e8;border-radius:6px;text-decoration:none;color:#0b2545;font-weight:700}.type-link.active{border-color:#f47b20;background:#fff7ea}.types{display:flex;flex-wrap:wrap;gap:8px}.types span{background:#f5f7fa;border:1px solid #d8e0e8;border-radius:6px;padding:8px 11px;font-weight:700}.search{width:100%;max-width:620px;padding:13px;border:1px solid #aeb8c4;border-radius:6px;margin:8px 0 20px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.card{display:flex;flex-direction:column;gap:5px;border:1px solid #d7e0e8;border-radius:8px;padding:14px;text-decoration:none}.card strong{color:#0b2545}.card span{color:#6a7888;font-size:.85rem}.missing{padding:60px}@media(max-width:850px){.grid{grid-template-columns:1fr}}</style>